// Teoría: lecciones cortas para entender el voleibol, con diagramas y quiz.
// Las reglas siguen las Reglas Oficiales de Voleibol FIVB 2025-2028 (se cita el número de regla).
// Las explicaciones técnicas y tácticas son propuesta de Remate basada en práctica común de entrenamiento.
// Para cambiar o agregar una lección: copia un bloque L(...) y respeta la forma. Cada pregunta: Q(texto, opciones, índice de la correcta (0 = primera), por qué).
//
// Bloques del cuerpo de una lección:
//   'texto'                 párrafo
//   { h: 'Subtítulo' }       subtítulo
//   { ul: [...] } / { ol: [...] }   lista con viñetas o numerada
//   { tip: 'texto' }         recuadro de dato o consejo
//   { dg: half(...), cap: 'pie' }   diagrama de cancha (ver court.js)
import { P, B, A, Z, T, half } from '../court.js';

export const UNITS = [
  { id: 'reglas', name: 'El juego y sus reglas', tag: 'Básico', min: 1, reto: 'teo-reglas',
    desc: 'La cancha, cómo se gana un punto, los toques, la red, la rotación y el líbero.' },
  { id: 'tecnica', name: 'Fundamentos técnicos', tag: 'Básico', min: 1, reto: 'teo-tecnica',
    desc: 'Cómo y por qué se hace cada gesto: posición, saque, recepción, colocación, remate, bloqueo y defensa.' },
  { id: 'sistemas', name: 'Posiciones y sistemas', tag: 'Intermedio', min: 3, reto: 'teo-sistemas',
    desc: 'Qué hace cada posición, los sistemas 4-2, 6-2 y 5-1, la recepción, los tiempos de ataque y la defensa.' },
  { id: 'tactica', name: 'Táctica y lectura de juego', tag: 'Avanzado', min: 4, reto: 'teo-tactica',
    desc: 'Side-out y contraataque, leer al rival, sacar con intención, comunicación, cabeza fría y estadística.' },
];
export const UNIT_BY_ID = Object.fromEntries(UNITS.map((u) => [u.id, u]));

const L = (id, unit, name, min, skill, intro, body, keys, quiz, src = '') => ({ id, unit, name, min, skill, intro, body, keys, quiz, src });
const Q = (q, opts, a, why) => ({ q, opts, a, why });
