export const lessonsOf = (unitId) => LESSONS.filter((l) => l.unit === unitId);

// Glosario: términos que vas a escuchar en la cancha.
export const GLOSSARY = [
  ['Ace', 'Saque que es punto directo: nadie lo recibe o el receptor no puede controlarlo.'],
  ['Antena', 'Varilla en cada orilla de la red que marca por dónde debe cruzar el balón. Si el balón la toca, es fuera.'],
  ['Armador', 'Otro nombre del colocador.'],
  ['Balón libre', 'Balón fácil que el rival regresa sin remate. Se grita «¡libre!».'],
  ['Bloqueo', 'Salto junto a la red para detener o frenar el ataque rival. No cuenta como toque.'],
  ['Bola alta', 'Colocación alta a las orillas: tercer tiempo.'],
  ['Break point', 'Punto que gana el equipo que saca.'],
  ['Central', 'Jugador que bloquea en todo el frente de la red y ataca rápido por el centro.'],
  ['Cobertura', 'Los compañeros se acercan al atacante por si el bloqueo regresa el balón.'],
  ['Colocación', 'Segundo toque del equipo, para dejarle el balón al atacante.'],
  ['Contraataque', 'Ataque después de bloquear o defender. También se le llama transición.'],
  ['Delantero', 'Jugador en zona 2, 3 o 4 al momento del saque.'],
  ['Diagonal', 'Remate cruzado, de una orilla de la cancha hacia la contraria.'],
  ['Doble toque', 'Falta: el balón toca dos partes del cuerpo una después de otra (fuera del primer toque del equipo).'],
  ['Falta de posición', 'Un jugador no está en su lugar de rotación cuando el sacador golpea.'],
  ['Finta', 'Toque suave por encima o al lado del bloqueo, a la zona corta.'],
  ['Flotado', 'Saque sin giro que cambia de trayectoria en el aire.'],
  ['Golpe al bloqueo', 'Remate a la mano de afuera del bloqueador para que el balón salga de la cancha.'],
  ['K1 y K2', 'Complejo 1 (recibir y atacar) y complejo 2 (sacar, defender y contraatacar).'],
  ['Líbero', 'Especialista en recepción y defensa, con camiseta de otro color. No saca, no bloquea y no remata arriba de la red.'],
  ['Línea', 'Remate paralelo a la línea lateral. También se dice «paralela».'],
  ['Opuesto', 'Atacante que juega en diagonal al colocador y ataca por zona 2.'],
  ['Penetración', 'Cuando el colocador que está atrás corre a la red para colocar.'],
  ['Pipe', 'Ataque de un zaguero por zona 6, desde atrás de la línea de ataque.'],
  ['Plataforma', 'Los antebrazos juntos y estirados con los que se recibe.'],
  ['Primer tiempo', 'Ataque rápido: el atacante ya está en el aire cuando el colocador toca el balón.'],
  ['Punta', 'Receptor-atacante: recibe y ataca sobre todo por zona 4.'],
  ['Rally point', 'Sistema en el que cada jugada da un punto, sin importar quién saca.'],
  ['Recepción', 'Primer toque después del saque rival.'],
  ['Retención', 'Falta: el balón se detiene o se acompaña en lugar de golpearse.'],
  ['Rotación', 'Avanzar una zona en el sentido de las manecillas del reloj al recuperar el saque.'],
  ['Side-out', 'Ganar el punto cuando el rival saca, y con eso recuperar el saque.'],
  ['Tiempo fuera', 'Pausa de 30 segundos que pide el entrenador; hay 2 por set.'],
  ['Zaguero', 'Jugador en zona 1, 5 o 6 al momento del saque. No bloquea ni remata arriba de la red desde la zona de frente.'],
  ['Zona de frente', 'Espacio entre la red y la línea de ataque (3 m).'],
];

